{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, c.service_name caller, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms, approx_quantile((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),0.5) client_extra_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.span_name='POST' AND s.span_name='POST /api/v1/basicservice/basic/travels' GROUP BY 1,2 UNION ALL SELECT 'norm', c.service_name, count(*), approx_quantile(c.duration,0.5)/1e6, approx_quantile(s.duration,0.5)/1e6, approx_quantile((epoch_ms(c.time)+c.duration/1e6)-(epoch_ms(s.time)+s.duration/1e6),0.5) FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.span_name='POST' AND s.span_name='POST /api/v1/basicservice/basic/travels' GROUP BY 1,2",
          "claim": "Travel's POST /basic/travels client waits ~1.5s beyond the basic server span (50ms server); normal gap is ~0."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, c.service_name caller, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_p50_ms, approx_quantile(s.duration,0.5)/1e6 server_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND s.span_name='POST /api/v1/basicservice/basic/travels' GROUP BY 1,2",
          "claim": "Same /basic/travels path from ts-travel2-service is normal (~55ms client, ~53ms server), so the delay is specific to travel's caller side."
        }
      ]
    },
    {
      "service": "ts-basic-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'ab' p, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravel' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravel' GROUP BY 1,2",
          "claim": "BasicController.queryForTravel self-time p95 rises from ~149ms to ~1261ms; it has no child spans."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'ab' p, metric, avg(value) avg_v, max(value) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-basic-service%' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value), max(value) FROM normal_metrics WHERE attr_k8s_pod_name LIKE 'ts-basic-service%' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2",
          "claim": "Basic-service pod CPU stays at or below normal levels, so the slowness is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, approx_quantile(s.duration,0.5)/1e6 callee_server_p50_ms, approx_quantile(c.duration,0.95)/1e6 caller_client_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND s.service_name='ts-basic-service' AND c.service_name='ts-travel-service' GROUP BY 1,2,3",
          "claim": "Travel's calls to basic /travel and /travels are slow, with basic's /travel server spans holding p95 over 1 second."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Route-plan's calls to travel have p95 around 1.7s in the abnormal window, against ~270ms normal."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan have p95 about 2.6s in the abnormal window, against ~1.0s normal."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Ui-dashboard's calls to travel-service have p95 about 1.75s in the abnormal window, against ~425ms normal."
        }
      ]
    }
  ]
}
```

